@staticmethod
def add(num1, num2):
    """
    Adds two big numbers.
    :param num1: The first number to add,str.
    :param num2: The second number to add,str.
    :return: The sum of the two numbers,str.
    >>> bigNum = BigNumCalculator()
    >>> bigNum.add("12345678901234567890", "98765432109876543210")
    '111111111011111111100'

    """
    # Remove any leading/trailing whitespace
    num1 = str(num1).strip()
    num2 = str(num2).strip()

    # Check for empty or invalid input
    if not num1 or not num2:
        return "0"

    # Handle signs
    num1_neg = num1.startswith('-')
    num2_neg = num2.startswith('-')

    if num1_neg and num2_neg:
        # Both negative: sum magnitudes and apply negative sign
        magnitude_sum = BigNumCalculator._add_magnitude(num1[1:], num2[1:])
        return '-' + magnitude_sum
    elif num1_neg != num2_neg:
        # Different signs: subtract smaller from larger, take sign of larger
        return BigNumCalculator._subtract_abs(num1, num2, num1_neg == (abs(num1) < abs(num2)))
    else:
        # Same sign: sum magnitudes
        if num1_neg:
            magnitude1 = num1[1:]
            magnitude2 = num2[1:]
            return '-' + BigNumCalculator._add_magnitude(magnitude1, magnitude2)
        else:
            return BigNumCalculator._add_magnitude(num1, num2)
